# ClampsClose: the swing clamps of the positioner faceplate close (the flange of the spool is clamped).
# The arms are two objects - turned away / on the flange rim - and the macro shows the right one.
# Generated by build_station2.py
from robodk.robolink import *
RDK = Robolink()
for name, visible in (('Clamp arms closed', True), ('Clamp arms open', False)):
    arms = RDK.Item(name, ITEM_TYPE_OBJECT)
    if arms.Valid():
        arms.setVisible(visible)
RDK.setParam("POS_CLAMPS", 'CLOSED')
